"""Public tests for the 2025 midterm, Problem 2 (witnesses).
Passing them does not establish correctness or complexity.
Witnesses are checked by their definition because a witness matrix is not unique."""
import copy
import random
import unittest
import witness as w

A2 = [[1, 1], [1, 0]]
B2 = [[0, 1], [1, 0]]
A3 = [[1, 1, 1], [1, 1, 0], [0, 1, 1]]
B3 = [[1, 0, 1], [0, 1, 0], [0, 1, 1]]


def is_bpwm(A, B, W):
    """True iff W is a Boolean product witness matrix for A.B (witnesses are 1-based, 0 = none)."""
    n = len(A)
    if len(W) != n or any(len(row) != n for row in W):
        return False
    for i in range(n):
        for j in range(n):
            witnesses = [k + 1 for k in range(n) if A[i][k] and B[k][j]]
            if witnesses and W[i][j] not in witnesses:
                return False
            if not witnesses and W[i][j] != 0:
                return False
    return True


def rand_bool(rng, n, density):
    return [[1 if rng.random() < density else 0 for _ in range(n)] for _ in range(n)]


class TestQ6(unittest.TestCase):
    def test_statement_example(self):
        self.assertEqual(w.compute_witness_trivial(A2, B2), [[2, 1], [0, 1]])

    def test_valid_on_random(self):
        rng = random.Random(6)
        for n in (1, 2, 3, 5, 8):
            for density in (0.0, 0.2, 0.6, 1.0):
                A, B = rand_bool(rng, n, density), rand_bool(rng, n, density)
                self.assertTrue(is_bpwm(A, B, w.compute_witness_trivial(A, B)), (A, B))

    def test_inputs_untouched(self):
        a, b = copy.deepcopy(A3), copy.deepcopy(B3)
        w.compute_witness_trivial(a, b)
        self.assertEqual((a, b), (A3, B3))


class TestQ7(unittest.TestCase):
    def test_expose_column(self):
        self.assertEqual(w.expose_column(A2), [[1, 2], [1, 0]])
        self.assertEqual(w.expose_column(A3), [[1, 2, 3], [1, 2, 0], [0, 2, 3]])
        self.assertEqual(w.expose_column([[0, 0], [0, 0]]), [[0, 0], [0, 0]])
        a = copy.deepcopy(A3)
        w.expose_column(a)
        self.assertEqual(a, A3)

    def test_unique_statement_example(self):
        self.assertEqual(w.compute_witness_unique(A2, B2), [[2, 1], [0, 1]])

    def test_unique_witnesses(self):
        # one 1 per row of A, so every entry of C has at most one witness
        rng = random.Random(7)
        for n in (1, 2, 4, 7):
            f = [rng.randrange(n) for _ in range(n)]
            A = [[1 if k == f[i] else 0 for k in range(n)] for i in range(n)]
            B = rand_bool(rng, n, 0.5)
            expected = [[(f[i] + 1) * B[f[i]][j] for j in range(n)] for i in range(n)]
            self.assertEqual(w.compute_witness_unique(A, B), expected)


class TestQ8(unittest.TestCase):
    def test_statement_examples(self):
        self.assertEqual(w.nullify_columns(A3, [1, 2]), [[1, 1, 0], [1, 1, 0], [0, 1, 0]])
        self.assertEqual(w.nullify_rows(B3, [1, 2]), [[1, 0, 1], [0, 1, 0], [0, 0, 0]])

    def test_extreme_sets(self):
        self.assertEqual(w.nullify_columns(A3, [1, 2, 3]), A3)
        self.assertEqual(w.nullify_rows(B3, [1, 2, 3]), B3)
        self.assertEqual(w.nullify_columns(A3, []), [[0] * 3 for _ in range(3)])
        self.assertEqual(w.nullify_rows(B3, []), [[0] * 3 for _ in range(3)])
        self.assertEqual(w.nullify_columns(A3, [3]), [[0, 0, 1], [0, 0, 0], [0, 0, 1]])

    def test_inputs_untouched(self):
        a, b = copy.deepcopy(A3), copy.deepcopy(B3)
        w.nullify_columns(a, [1])
        w.nullify_rows(b, [1])
        w.compute_witness_restricted(a, b, [1, 2])
        self.assertEqual((a, b), (A3, B3))

    def test_restricted_statement_example(self):
        self.assertEqual(w.compute_witness_restricted(A3, B3, [1, 2]), [[1, 2, 1], [1, 2, 1], [0, 2, 0]])

    def test_restricted_full_set_matches_unique(self):
        self.assertEqual(w.compute_witness_restricted(A2, B2, [1, 2]), [[2, 1], [0, 1]])


class TestQ10(unittest.TestCase):
    def test_statement_matrices(self):
        random.seed(10)
        for _ in range(20):
            self.assertTrue(is_bpwm(A3, B3, w.compute_witness_random(A3, B3)))

    def test_random_matrices(self):
        random.seed(11)
        rng = random.Random(12)
        for n in (1, 2, 3, 5, 8, 12):
            for density in (0.0, 0.15, 0.5, 1.0):
                A, B = rand_bool(rng, n, density), rand_bool(rng, n, density)
                self.assertTrue(is_bpwm(A, B, w.compute_witness_random(A, B)), (n, density))

    def test_inputs_untouched(self):
        a, b = copy.deepcopy(A3), copy.deepcopy(B3)
        w.compute_witness_random(a, b)
        self.assertEqual((a, b), (A3, B3))


if __name__ == '__main__':
    unittest.main(verbosity=2)
